import{_ as e,o as r,c as l,a2 as t}from"./chunks/framework.DfDAiEgj.js";const i="/2bPM/img/hand_draw.png",o="/2bPM/img/PS.png",n="/2bPM/img/grey_axure.png",h="/2bPM/img/lineframe_chart.jpg",s="/2bPM/img/after_validate.png",g=JSON.parse('{"title":"原型设计","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/prototype_design.md","filePath":"knowledge/prototype_design.md","lastUpdated":null}'),p={name:"knowledge/prototype_design.md"};function d(u,a,c,b,m,f){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="原型设计" tabindex="-1">原型设计 <a class="header-anchor" href="#原型设计" aria-label="Permalink to &quot;原型设计&quot;">​</a></h1><p>重点：<strong>可视+互动</strong></p><p>在产品定义阶段，用户参与产品设计和体验，解决75%的问题才是最高效的。</p><p>原型的定义:是产品方案的输出物 <a href="https://www.zhihu.com/question/55997614/answer/615628989" target="_blank" rel="noreferrer">1</a>。</p><p><strong>目的</strong>：将想法转化为高效传达给其他人（程序员和ui）或者与用一起测试的形式,并且随看时间的推移,可以持续进行调整。你可以用它来自如的测试未完成的想法,从而达到最佳的结果。接受反馈,将反馈再次融入到你的原型设计中。只要对方能够听懂看懂就可以了，所以<strong>使用手绘原型</strong>是最高效率的方法。</p><h2 id="原型设计和评审" tabindex="-1">原型设计和评审 <a class="header-anchor" href="#原型设计和评审" aria-label="Permalink to &quot;原型设计和评审&quot;">​</a></h2><p>由产品经理主导的。基于运营的需求设计原型，在原型设计完后，要经过内部评审和外部评审。</p><p>在内部评审中，产品经理要召集数据中台的架构师、模型设计师、数据开发工程师、后端开发工程师、前端开发工程师、UI设计师、测试工程师，说明整个功能的价值和详细的<strong>业务流程、操作流程</strong>，确保大家理解一致。</p><p>接下来，产品经理和运营人员要针对原型做一次外部评审，把<strong>有歧义的地方一并解决</strong>。</p><p>对于比较重要的功能，产品经理需要发邮件让运营人员进一步确认，并同步给所有的产品/运营人员，保证大家的口径一致。<a href="https://www.zhihu.com/question/461160785/answer/2007476874" target="_blank" rel="noreferrer">11</a></p><h2 id="原型设计时需要思考的问题-9" tabindex="-1">原型设计时需要思考的问题 <a href="https://zhuanlan.zhihu.com/p/56954145" target="_blank" rel="noreferrer">9</a> <a class="header-anchor" href="#原型设计时需要思考的问题-9" aria-label="Permalink to &quot;原型设计时需要思考的问题 [9]&quot;">​</a></h2><ol><li>原型需要达到的目的是什么？</li><li>此原型的用户是谁？</li><li>用户的使用场景是什么？</li><li>需要提供什么样的用户体验？</li><li>后续的工作流程如何把握？</li></ol><h3 id="目的-用户-使用场景" tabindex="-1">目的 + 用户 + 使用场景： <a class="header-anchor" href="#目的-用户-使用场景" aria-label="Permalink to &quot;目的 + 用户 + 使用场景：&quot;">​</a></h3><ol><li><p>将需求可视化：产品经理通过调研或发掘，或者是Leader直接向下传达的需求，将其可视化，需要形象准确地描绘出来，以便对方可以直观理解，快速达成共识；</p></li><li><p>完成设计协作：在产品开发流程中，对于确定的需求和功能策划，需要在进入UI设计阶段之前将原型稿确认，便于在正式投入精美的设计之前可以先把产品的方向以及功能结构确定下来，避免设计返工；</p></li><li><p>向甲方爸爸展示：对于一些外包服务型公司，在跟甲方或者客户爸爸确定需求后，需要第一时间将双方理解的内容快速展示出来，以便快速发现问题然后沟通调整，为之后交付正确的解决方案做准备，也同时尽量避免因前期客户信息不同步造成的项目风险。</p></li></ol><p>针对以上三个场景，就诞生了三种典型的原型稿绘制形态：草绘线框图、低/中保真原型、高保真原型。</p><h2 id="用户体验-即提供不同原型" tabindex="-1">用户体验，即提供不同原型 <a class="header-anchor" href="#用户体验-即提供不同原型" aria-label="Permalink to &quot;用户体验，即提供不同原型&quot;">​</a></h2><h3 id="草绘-手绘原型" tabindex="-1">草绘/手绘原型 <a class="header-anchor" href="#草绘-手绘原型" aria-label="Permalink to &quot;草绘/手绘原型&quot;">​</a></h3><p>线框图，不可交互，手绘来最快速的表现产品轮廓手绘原型在初期验证想法时非常高效，也方便讨论和重构，同时也适合敏捷开发时快速出原型；只展示大概的原型界面框架、关键内容和核心的页面流，可以是手绘或使用软件工具。特点是：快。<a href="https://www.zhihu.com/question/461160785/answer/2007476874" target="_blank" rel="noreferrer">11</a></p><p><img src="'+i+'" alt="手绘原型"></p><h3 id="低-中保真原型" tabindex="-1">低/中保真原型 <a class="header-anchor" href="#低-中保真原型" aria-label="Permalink to &quot;低/中保真原型&quot;">​</a></h3><p>低保真原型：由图形设计软件制作而成，不可交互。最常用的软件是Photoshop和Fireworks，相对手绘原型，灰模更加清晰和整洁，也适用于正式场合的PPT形式宣讲，或打印在纸上，来展示主业务流程。平面原型：如果不会使用图形软件也可以使用Axure RP设计，相比交互原型，灰模原型只是缺少交互效果，仅仅是将产品需求以线框结构的方式展示出来，让产品需求更加规整的直观展现。<a href="https://tangjie.me/blog/114.html" target="_blank" rel="noreferrer">8</a>低保真 Axure实战:ref:<code>page_Axure</code></p><p><img src="'+o+'" alt="PS设计"></p><p><img src="'+n+'" alt="Axure平面原型"></p><p>中保真原型：可简单交互（点击页面跳转），在保证原型基础的规范性基础上，还可以让专业的交互、视觉设计师有一定的发挥空间来简单配色并配图，但字体、配色和配图不完美；该种形态多用于上述第二种场景，多用于在工作流程中的交互、设计协作，</p><h3 id="高保真原型" tabindex="-1">高保真原型 <a class="header-anchor" href="#高保真原型" aria-label="Permalink to &quot;高保真原型&quot;">​</a></h3><p>开发和设计参与，原型可交互，可录入信息，可以实现所有流程，有动画效果，字体、配色和配图与真实产品一致。该种形态多用于上述第三种场景，即在向客户交付方案前的成果展示，为了便于趋近真实的产品，方便客户可以快速理解和决策是否要直接投入开发成本；高保真 Axure实战:ref:<code>page_done_Axure</code></p><h3 id="线框图" tabindex="-1">线框图 <a class="header-anchor" href="#线框图" aria-label="Permalink to &quot;线框图&quot;">​</a></h3><p><img src="'+h+'" alt="线框图7"></p><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><h2 id="反馈圈分类" tabindex="-1">反馈圈分类 <a class="header-anchor" href="#反馈圈分类" aria-label="Permalink to &quot;反馈圈分类&quot;">​</a></h2><ul><li>团队成员或朋友：团队成员，公司员工，社交圈朋友。特点：容易找到，易与沟通。使用低保真原型，了解主要流程是否存在问题。</li><li>行业专家：相关领域产品经理和产品专家，他们了解目标市场。特点：能提出逻辑清晰的意见。使用低，中保真原型。</li><li>客户：目标市场的客户。使用中、高保真原型，他们会提供非常棒的反馈意见</li><li>客户的客户：特定人群应用，如投资人等。使用高保真原型展示，获取真实反馈。</li></ul><h2 id="信息收集工具" tabindex="-1">信息收集工具 <a class="header-anchor" href="#信息收集工具" aria-label="Permalink to &quot;信息收集工具&quot;">​</a></h2><ul><li>记笔记；</li><li>手机录音；</li><li>在用户允许的情况下，录入表情；</li><li>原型操作过程手机或电脑页面录制。</li></ul><h2 id="工具推荐" tabindex="-1">工具推荐 <a class="header-anchor" href="#工具推荐" aria-label="Permalink to &quot;工具推荐&quot;">​</a></h2><ul><li>低保真-线框-纸质原型：可以用于产品团队内部交流使用，通过头脑风暴，跑通住业务流程。确定MVP（Minimum Viable Product, MVP）方案，确定中保真原型方案。</li><li>中保真原型--墨刀或axure：对于朋友、专家和客户可以提供具有交互功能的可录入信息的中保真原型，设计尽量保证完成，以便于手机用户的全部操作行为。</li><li>高保真原型：开发资源富裕的团队，如微信团队，可以实现每个想法的高保真原型快速输出和范围测试。</li></ul><h3 id="墨刀" tabindex="-1">墨刀 <a class="header-anchor" href="#墨刀" aria-label="Permalink to &quot;墨刀&quot;">​</a></h3><p>墨刀<a href="https://zhuanlan.zhihu.com/p/33997501" target="_blank" rel="noreferrer">3</a>是一个款移动端原型制作工具，原型制作制作方便，可以快捷添加一些简单的交互动画，信息录入，逻辑判断等功能，支持微信分享，便于传播手机信息。</p><p>挑一种学一下就可以了（最易学习的是墨刀，Sketch学会了用起来最顺手快捷，Axure应该算是最不好用的一个了</p><h2 id="产品演进路线图-2" tabindex="-1">产品演进路线图 <a href="https://www.bilibili.com/video/BV1254y1D7Ht?from=search&amp;seid=14167562900175777805" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#产品演进路线图-2" aria-label="Permalink to &quot;产品演进路线图 [2]&quot;">​</a></h2><p>产品演进路线图是为了给产品的利益相关者以及团队呈现产品长远发展的构思。使团队内部和利益相关者对项目的长远发展一目了然并达成共识</p><ul><li>近期:为了满足需求必须要包含的功能</li><li>中期:关注范围广、有一定的灵活性的功能</li><li>远期:顶层设计、宽泛的范围、更加灵活的功能</li></ul><h2 id="绘制操作流程-9" tabindex="-1">绘制操作流程 <a href="https://zhuanlan.zhihu.com/p/56954145" target="_blank" rel="noreferrer">9</a> <a class="header-anchor" href="#绘制操作流程-9" aria-label="Permalink to &quot;绘制操作流程 [9]&quot;">​</a></h2><ul><li>对于交互比较复杂的操作，需要绘制操作流程图，可以是Visio图，也可以是页面跳转说明</li><li>操作流程图中形状需要根据标准进行选择</li><li>需要包含正常操作逻辑和异常操作逻辑</li></ul><h2 id="原型发布和导出-9" tabindex="-1">原型发布和导出 <a href="https://zhuanlan.zhihu.com/p/56954145" target="_blank" rel="noreferrer">9</a> <a class="header-anchor" href="#原型发布和导出-9" aria-label="Permalink to &quot;原型发布和导出 [9]&quot;">​</a></h2><ul><li>原型发布时选择生成HTML文件，在相应的文件夹中，点击start.html就可以通过浏览器打开发布的文件（在线太慢，一般建议导出使用）</li><li>原型导出时，也可以将所有相关页面导出为PNG图片</li><li>给前端提供原型时，最好分别提供HTML文件和PNG图片</li></ul><h2 id="验证-validate-4" tabindex="-1">验证（Validate） <a href="https://www.jianshu.com/p/cb6ae5a3f3fa" target="_blank" rel="noreferrer">4</a> <a class="header-anchor" href="#验证-validate-4" aria-label="Permalink to &quot;验证（Validate） [4]&quot;">​</a></h2><p>验证产品原型</p><p><img src="'+s+'" alt="验证产品原型后续工作10"></p><h2 id="题目-5" tabindex="-1">题目 <a href="https://blog.nowcoder.net/n/9bd8651faead4a73ae344be0b74128de" target="_blank" rel="noreferrer">5</a> <a class="header-anchor" href="#题目-5" aria-label="Permalink to &quot;题目 [5]&quot;">​</a></h2><p>Axure文件的后缀名RP（Rapid Prototyping）指快速原型</p><ul><li>Action sheet：动作菜单/动作面板/行动列表</li><li>Picker：选择器/拾取器</li><li>Toast：吐司提示 产品设计中常把出现在屏幕中、用以引起注意，短暂出现后消失的提醒控件叫做</li><li>Status bar：全局修改状态栏</li><li>More: <a href="https://www.jianshu.com/nb/9076183" target="_blank" rel="noreferrer">6</a></li></ul>',51)])])}const P=e(p,[["render",d]]);export{g as __pageData,P as default};
